const agents = [
  {id:"producer",name:"Мира",role:"Продюсер",state:"active",description:"Собирает контекст, держит цель и управляет всей командой."},
  {id:"researcher",name:"Лекс",role:"Исследователь",description:"Находит реальные боли, желания и язык аудитории."},
  {id:"strategist",name:"Софи",role:"Маркетинг-стратег",description:"Строит позиционирование, оффер и путь к покупке."},
  {id:"smm",name:"Нова",role:"SMM-стратег",description:"Превращает стратегию в рубрики, связки и календарь."},
  {id:"copywriter",name:"Макс",role:"Копирайтер",description:"Пишет истории, посты, карусели и продающие тексты."},
  {id:"reels",name:"Рэй",role:"Reels-сценарист",description:"Создаёт честные хуки и сценарии коротких видео."},
  {id:"visual",name:"Итан",role:"Визуальный продюсер",description:"Отвечает за арт-дирекшн, обложки и визуальные метафоры."},
  {id:"guardian",name:"Грейс",role:"Brand Guardian",description:"Проверяет факты, голос, стратегию и качество материалов."},
  {id:"analyst",name:"Алекс",role:"Аналитик",description:"Связывает публикации, обращения, лиды и продажи."},
];
const positions=["0% 0%","50% 0%","100% 0%","0% 50%","50% 50%","100% 50%","0% 100%","50% 100%","100% 100%"];
const memoryNames={brief:"Бренд-бриф",product:"Продукт и оффер",audience:"Аудитория",voice:"Авторский голос",strategy:"Стратегия",evidence:"Доказательства",calendar:"Контент-календарь",decisions:"Решения",feedback:"Обратная связь",analytics:"Аналитика"};
let state=null,selectedMemory="brief",selectedAgent="producer";
const histories=JSON.parse(localStorage.getItem("nexus-chat-history")||"{}");
const $=(s)=>document.querySelector(s), $$=(s)=>[...document.querySelectorAll(s)];

function avatarStyle(index){return `--avatar-pos:${positions[index]}`}
function agentCard(agent,index,large=false){return `<button class="agent-card" data-chat="${agent.id}"><div class="avatar" style="${avatarStyle(index)}"></div><span class="agent-state ${agent.state||""}"></span><div class="agent-meta"><b>${agent.name}</b><small>${agent.role}${agent.state==="active"?" · работает":" · ожидает"}</small>${large?`<small class="agent-description">${agent.description}</small>`:""}</div></button>`}
function renderTeam(){ $("#teamStrip").innerHTML=agents.map((a,i)=>agentCard(a,i)).join(""); $("#teamGrid").innerHTML=agents.map((a,i)=>agentCard(a,i,true)).join(""); bindChatButtons(); }

function renderCalendar(target,compact=false){const rows=state?.calendarRows||[];if(compact){$(target).innerHTML=rows.length?rows.slice(0,3).map(r=>`<div class="milestone active"><i>•</i><div><b>${r["Главный смысл"]||r["Формат"]}</b><small>${r["Дата/окно"]||"Без даты"} · ${r["Статус"]||"Черновик"}</small></div></div>`).join(""):`<div class="mini-empty"><div class="empty-spark">✦</div><b>Календарь ждёт стратегию</b><p>Сначала команда завершит распаковку и выберет приоритетный сегмент.</p></div>`;return}const days=["ПН","ВТ","СР","ЧТ","ПТ","СБ","ВС",...Array.from({length:35},(_,i)=>String(i+1))];$(target).innerHTML=`<div class="calendar-week">${days.map((d,i)=>`<div class="day ${i<7?"head":""} ${i===9?"today":""}">${d}</div>`).join("")}</div>${rows.length?"":`<div class="calendar-empty"><b>План ещё не сформирован</b><p>Это честное состояние проекта: случайными темами календарь не заполняем.</p></div>`}`}

function escapeHtml(text){return text.replace(/[&<>]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;"}[c]))}
function markdownLite(md){return escapeHtml(md).split("\n").map(line=>{if(line.startsWith("## "))return `<h2>${line.slice(3)}</h2>`;if(line.startsWith("# "))return `<h1>${line.slice(2)}</h1>`;if(line.startsWith("- [ ]"))return `<div class="check">○ ${line.slice(5)}</div>`;if(line.startsWith("- "))return `<li>${line.slice(2)}</li>`;if(!line.trim())return "<br>";return `<div>${line.replace(/`([^`]+)`/g,"<code>$1</code>").replace(/\*\*([^*]+)\*\*/g,"<b>$1</b>")}</div>`}).join("")}
function renderMemory(){const navKeys=["brief","product","audience","voice","strategy","evidence","calendar","decisions","feedback","analytics"];$("#memoryNav").innerHTML=navKeys.map(k=>`<button class="memory-link ${k===selectedMemory?"active":""}" data-memory="${k}"><b>${memoryNames[k]}</b><small>${state?.files[k]?.status||"not_started"}</small></button>`).join("");const file=state?.files[selectedMemory];if(file){$("#memoryTitle").textContent=memoryNames[selectedMemory];$("#memoryStatus").textContent=file.status;$("#memoryContent").innerHTML=markdownLite(file.markdown);$("#copyPath").dataset.path=file.path}$$('[data-memory]').forEach(b=>b.onclick=()=>{selectedMemory=b.dataset.memory;renderMemory()})}

async function loadState(){try{$("#syncLabel").textContent="Читаю память…";const response=await fetch("/api/state");if(!response.ok)throw new Error();state=await response.json();renderCalendar("#miniCalendar",true);renderCalendar("#fullCalendar");renderMemory();$("#contentCount").textContent=`${state.contentRows.length} материалов`;$("#syncLabel").textContent="Память синхронизирована"}catch{$("#syncLabel").textContent="Нет связи с сервером"}}
function showView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.rail-button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));const titles={overview:"Доброе утро, Дмитрий",team:"Ваша команда",content:"Контент и публикации",memory:"Общая память",analytics:"Результаты и гипотезы"};$("#viewTitle").textContent=titles[id]||"NEXUS";window.scrollTo({top:0,behavior:"smooth"})}

function saveHistories(){localStorage.setItem("nexus-chat-history",JSON.stringify(histories))}
function renderChat(){const agent=agents.find(a=>a.id===selectedAgent),index=agents.indexOf(agent);$("#chatAvatar").style.cssText=avatarStyle(index);$("#chatName").textContent=agent.name;$("#chatRole").textContent=`${agent.role} · на связи`;const history=histories[selectedAgent]||[];$("#chatMessages").innerHTML=(history.length?history:[{role:"assistant",text:selectedAgent==="producer"?"Я на связи. Продолжим распаковку или разберём текущее состояние проекта?":"Я вижу общую память проекта и готов помочь в своей зоне ответственности."}]).map(m=>`<div class="bubble ${m.role==="user"?"user":"agent"}">${escapeHtml(m.text)}</div>`).join("");$("#chatMessages").scrollTop=$("#chatMessages").scrollHeight}
function openChat(id){selectedAgent=id;renderChat();$("#chatDrawer").classList.add("open");$("#scrim").classList.add("open");$("#chatDrawer").setAttribute("aria-hidden","false");setTimeout(()=>$("#chatInput").focus(),250)}
function closeChat(){$("#chatDrawer").classList.remove("open");$("#scrim").classList.remove("open");$("#chatDrawer").setAttribute("aria-hidden","true")}
function bindChatButtons(){$$('[data-chat]').forEach(b=>b.onclick=()=>openChat(b.dataset.chat))}
async function sendMessage(message){if(!localStorage.getItem("nexus-codex-consent")){const approved=window.confirm("Чтобы специалист ответил, сообщение и необходимый контекст из проекта будут обработаны облачным сервисом Codex. Файлы останутся в режиме только для чтения. Продолжить?");if(!approved)return;localStorage.setItem("nexus-codex-consent","yes")}histories[selectedAgent]??=[];histories[selectedAgent].push({role:"user",text:message});saveHistories();renderChat();const thinking=document.createElement("div");thinking.className="bubble agent thinking";thinking.textContent="Изучаю память и формулирую ответ…";$("#chatMessages").append(thinking);$("#chatMessages").scrollTop=$("#chatMessages").scrollHeight;try{const response=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({agentId:selectedAgent,message,history:histories[selectedAgent].slice(-8,-1)})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Ошибка связи");histories[selectedAgent].push({role:"assistant",text:data.reply})}catch(error){histories[selectedAgent].push({role:"assistant",text:`Не удалось получить ответ: ${error.message}. Проверьте, что локальный сервер и Codex запущены.`})}saveHistories();renderChat()}

renderTeam();loadState();
$$('.rail-button').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-view-jump]').forEach(b=>b.onclick=()=>showView(b.dataset.viewJump));$("#refreshButton").onclick=loadState;$("#closeChat").onclick=closeChat;$("#scrim").onclick=closeChat;$("#chatForm").onsubmit=(e)=>{e.preventDefault();const input=$("#chatInput"),message=input.value.trim();if(message){input.value="";sendMessage(message)}};$("#chatInput").onkeydown=(e)=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();$("#chatForm").requestSubmit()}};$("#copyPath").onclick=async()=>{const path=$("#copyPath").dataset.path||"";await navigator.clipboard.writeText(path);const toast=$("#toast");toast.textContent=`Скопировано: ${path}`;toast.classList.add("show");setTimeout(()=>toast.classList.remove("show"),1800)};bindChatButtons();$$('[data-open="brief"]').forEach(b=>b.onclick=()=>{selectedMemory="brief";showView("memory");renderMemory()});
